import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { listSpaceMembers } from "../handlers/listSpaceMembers";
import type { ApiError } from "../runtime/client";
import type { SpacePartition } from "../types/SpacePartition";

type Data = Awaited<ReturnType<typeof listSpaceMembers>>;

export function useListSpaceMembers(
  spaceId: SpacePartition,
  bookmark?: string | null,
  query?: string | null,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["listSpaceMembers", spaceId, bookmark, query],
    queryFn: () => listSpaceMembers(spaceId, bookmark, query),
    ...options,
  });
}
